from shelf import books, cli, export


def setup_function():
    books.clear()


def test_export_empty_shelf():
    assert export.export_csv() == "title,author\n"


def test_export_two_books():
    books.add("Dune", "Frank Herbert")
    books.add("Emma", "Jane Austen")
    assert export.export_csv() == "title,author\nDune,Frank Herbert\nEmma,Jane Austen\n"


def test_export_quotes_comma_in_title():
    books.add("Dune, Messiah", "Frank Herbert")
    assert export.export_csv() == 'title,author\n"Dune, Messiah",Frank Herbert\n'


def test_cli_export(capsys):
    books.add("Dune", "Frank Herbert")
    assert cli.main(["export"]) == 0
    assert capsys.readouterr().out == export.export_csv()

import csv
import io

from shelf import books


def export_csv():
    out = io.StringIO()
    w = csv.writer(out, lineterminator="\n")
    w.writerow(["title", "author"])
    for b in books.all_books():
        w.writerow([b["title"], b["author"]])
    return out.getvalue()

